def pre(p, q):
    # Reachable score pairs for a game that stops at the first win:
    # the lead can be at most 2, except for the final winning point
    # from (4,0)/(0,4) or from scores with both at most 4 and lead at most 4.
    d = p - q
    return And(
        p >= 0,
        q >= 0,
        Or(
            And(d >= -2, d <= 2),
            And(d >= -4, d <= 4, p <= 4, q <= 4),
        ),
    )

def post(p, q, r):
    win_a = And(p >= 4, p - q >= 2)
    win_b = And(q >= 4, q - p >= 2)
    return r == If(win_a, 1, If(win_b, 2, 0))
